// Regenerates src/data/hosts.ts from canonical src/data/hosts.json (offline).
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const data = JSON.parse(readFileSync(join(root, "src/data/hosts.json"), "utf8"));
const out =
  "// GENERATED by scripts/gen-hosts.mjs from hosts.json. Do not edit.\n" +
  "export interface HostRule {\n  pattern: string;\n  class: \"good\" | \"telemetry\";\n  vendor: string;\n  category: string;\n  source: string;\n}\n" +
  "export interface HostData {\n  version: number;\n  updated: string;\n  rules: HostRule[];\n}\n" +
  "export const hostData: HostData = " + JSON.stringify(data, null, 2) + ";\n";
writeFileSync(join(root, "src/data/hosts.ts"), out);
console.log(`wrote src/data/hosts.ts (${data.rules.length} rules)`);
